import React,{useEffect,useRef,useState} from 'react'; import { FiArrowDownRight } from 'react-icons/fi'; import './Process.css';
const steps=[['01','Build the right team','We bring together the product, design, and engineering expertise your project needs from day one.'],['02','Plan the sprint','We turn goals into a focused plan with clear priorities, meaningful milestones, and room to learn.'],['03','Shape the architecture','We create a flexible technical foundation that supports today’s launch and tomorrow’s growth.'],['04','Stay close to the work','Regular check-ins and working demos keep every decision visible, practical, and on track.'],['05','Review with care','Every release gets thoughtful product and code review before it reaches the people who matter.'],['06','Deliver in meaningful steps','We ship in smaller, useful increments so you see progress early and can respond with confidence.']];
const Process=()=>{const ref=useRef(null);const [visible,setVisible]=useState(false);useEffect(()=>{const observer=new IntersectionObserver(([entry])=>{if(entry.isIntersecting){setVisible(true);observer.disconnect()}},{threshold:.14});if(ref.current)observer.observe(ref.current);return()=>observer.disconnect()},[]);return <section className={`process-section ${visible?'is-visible':''}`} ref={ref}><div className="process-heading"><div><span className="mini-rule"/><p className="section-kicker">How we work</p><h2>From first move<br/><b>to forward momentum.</b></h2></div><p>A focused delivery rhythm keeps everyone close to the work, clear on the next decision, and confident in the direction.</p></div><div className="process-grid">{steps.map(([number,title,copy],index)=><article className="process-step" key={number}><span className="step-number">{number}</span><span className="step-arrow"><FiArrowDownRight/></span><h3>{title}</h3><p>{copy}</p></article>)}</div></section>};
export default Process;
